class Solution { public: bool isPossibleDivide(vector<int>& nums,int k){if(nums.size()%k)return false;map<int,int> frequency;for(int value:nums)++frequency[value];while(!frequency.empty()){int start=frequency.begin()->first;for(int value=start;value<start+k;++value){auto it=frequency.find(value);if(it==frequency.end())return false;if(!--it->second)frequency.erase(it);}}return true;} };
